/**
 * The FlowDetail header shows the wire HTTP version next to the Protocol
 * badge. HTTP/2 streams are recorded as `protocol: "http"`, so the version
 * meta item is the only place an h2 / h2c flow is distinguishable from
 * HTTP/1.x. Fixtures are real `query resource=flow` responses generated by
 * internal/mcp/webui_http_fixture_test.go.
 */

import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import type { FlowDetailResult } from "../../lib/mcp/types.js";
import { HttpVersionMeta } from "./HttpVersionMeta.js";
import h1Text from "./__fixtures__/h1-flow.response.json?raw";
import h2Text from "./__fixtures__/h2-flow.response.json?raw";
import h2cText from "./__fixtures__/h2c-flow.response.json?raw";

const h1 = JSON.parse(h1Text) as FlowDetailResult;
const h2 = JSON.parse(h2Text) as FlowDetailResult;
const h2c = JSON.parse(h2cText) as FlowDetailResult;

function render(flow: Pick<FlowDetailResult, "protocol" | "http_version">): string {
  return renderToStaticMarkup(createElement(HttpVersionMeta, { flow }));
}

/** Text content of the badge inside the rendered meta item. */
function badgeText(html: string): string {
  return /<span class="badge[^"]*">([^<]*)<\/span>/.exec(html)?.[1] ?? "";
}

describe("HttpVersionMeta", () => {
  it("fixtures are HTTP flows that differ only by http_version", () => {
    expect([h1.protocol, h2.protocol, h2c.protocol]).toEqual(["http", "http", "http"]);
    expect([h1.http_version, h2.http_version, h2c.http_version]).toEqual(["http/1.1", "h2", "h2c"]);
  });

  it("shows h2 for a recorded HTTP/2-over-TLS flow, highlighted", () => {
    const html = render(h2);
    expect(html).toContain("HTTP version");
    expect(badgeText(html)).toBe("h2");
    expect(html).toContain("badge--info");
  });

  it("shows h2c for a recorded cleartext HTTP/2 flow, highlighted", () => {
    const html = render(h2c);
    expect(badgeText(html)).toBe("h2c");
    expect(html).toContain("badge--info");
  });

  it("shows http/1.1 verbatim for an HTTP/1.1 flow, never h2", () => {
    const html = render(h1);
    expect(badgeText(html)).toBe("http/1.1");
    expect(html).not.toContain(">h2<");
    expect(html).not.toContain("badge--info");
  });

  it("renders nothing when the flow has no http_version", () => {
    expect(render({ protocol: "ws" })).toBe("");
    expect(render({ protocol: "http", http_version: "" })).toBe("");
  });
});
